 function updateLabScare(){if(disaster>=8.35&&!rushSoundPlayed){rushSoundPlayed=true;scareSound('rush');}if(disaster>=8.78&&!labScare){stopSpeech();labScare=createCaptureScare();scareSound('impact');}labScareActive=!!labScare&&disaster<10.63;document.getElementById('intro-task').hidden=labScareActive;document.getElementById('intro-skip').hidden=labScareActive;if(labScareActive){const pose=labScare.update(disaster-8.78,innerWidth/innerHeight);document.getElementById('intro-line').hidden=true;document.getElementById('intro-fade').style.opacity=String(pose.fade);}else if(labScare){document.getElementById('intro-fade').style.opacity='1';}}
 function finish(){if(ended)return;ended=true;homeDetails?.bag.removeFromParent();scene.attach(camera);ignitionSequence?.dispose();phoneIntro?.dispose();onDrive(false);stopSpeech();document.getElementById('intro').hidden=true;if(labScare)labScare.scene.traverse(o=>{o.geometry?.dispose();o.material?.dispose();});group.traverse(o=>{o.geometry?.dispose();if(o.material){o.material.map?.dispose();o.material.dispose();}});done();}
 home();document.getElementById('intro-task').hidden=false;document.getElementById('intro-skip').hidden=false;return{get scene(){return labScareActive?labScare.scene:scene;},get camera(){return labScareActive?labScare.camera:camera;},update,interact,finish,setSpeaker(name){activeSpeaker=name||'';},get robotEscape(){return robotEscape;},get labScareActive(){return labScareActive;},get actors(){return people;},get spider(){return spider;},get alarm(){return alarm;},get doorClosed(){return doorClosed;},get handsRaised(){return defensiveHands.g.visible;},get brokenGlass(){return broken;},get shards(){return shards;},get silk(){return silkLine;},get ceilingThread(){return ceilingThread;},get labButton(){return labButton;},get labPress(){return !!labPress;},get homeDetails(){return homeDetails;},get bagWorn(){return bagWorn;},get bagTravel(){return !!bagTravel;},get roadVehicle(){return roadVehicle;},get manor(){return manor;},get roadProps(){return roadProps;},get ignitionSequence(){return ignitionSequence;},get phoneHoldingHand(){return phoneIntro?.holdingHand;},get phoneTappingHand(){return phoneIntro?.tappingHand;},get phone(){return phoneIntro?.phone;},get traffic(){return traffic;},get engineOn(){return engineOn;},get wardrobe(){return wardrobe;},get dressing(){return !!dressing;},get yard(){return yard;},get enteringCar(){return !!enteringCar;},get phoneState(){return phoneIntro?.state;},get phase(){return phase;},get step(){return step;},target};
